SELECT t, SUM(v) FROM (SELECT (SELECT th.tier FROM seller_tier_history th WHERE th.seller_id = oi.seller_id AND CAST(o.order_at AS DATE) >= th.valid_from AND CAST(o.order_at AS DATE) < th.valid_to) AS t, oi.line_total_bdt AS v FROM order_items oi JOIN orders o ON o.order_id = oi.order_id WHERE o.is_deleted = FALSE AND o.status IN ('delivered', 'in_transit', 'returned') AND o.order_at >= TIMESTAMP '2024-10-01 00:00:00' AND o.order_at < TIMESTAMP '2025-01-01 00:00:00') x WHERE t IN ('gold', 'silver') GROUP BY t
